```json
{
  "openapi": "3.1.0",
  "info": {
    "title": "Modulr API",
    "description": "Modulr API",
    "license": {
      "name": "© Modulr Finance",
      "url": "https://www.modulrfinance.com"
    },
    "version": "1.0"
  },
  "servers": [
    {
      "url": "https://api-sandbox.modulrfinance.com/api-sandbox-token"
    }
  ],
  "security": [
    {
      "modulo_security": []
    }
  ],
  "tags": [
    {
      "name": "Customers",
      "description": "Operations on Customers"
    }
  ],
  "paths": {
    "/customers": {
      "get": {
        "tags": [
          "Customers"
        ],
        "summary": "Retrieve customers using filters",
        "description": "Either using unique references, such as customer ID, or filter parameters, such as verification status, get details of any customers found.",
        "operationId": "getCustomers",
        "parameters": [
          {
            "name": "id",
            "in": "query",
            "description": "ID of Customer(s) to fetch",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "$ref": "#/components/schemas/account.id"
            }
          },
          {
            "name": "delegateId",
            "in": "query",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "$ref": "#/components/schemas/account.delegateId"
            }
          },
          {
            "name": "q",
            "in": "query",
            "description": "Query parameter. ID, name or external reference of customer to search for",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Query parameter. ID, name or external reference of customer to search for"
            }
          },
          {
            "name": "type",
            "in": "query",
            "description": "Type to filter, can be one of:\n1. LLC -> limited company\n2. PLC -> publicly listed company\n3. SOLETRADER -> sole trader\n4. OPARTNRSHP -> ordinary partnership\n5. LPARTNRSHP -> limited partnership\n6. LLP -> limited liability partnership\n7. INDIVIDUAL -> individual consumer\n8. PCM_INDIVIDUAL -> partner clearing model individual consumer\n9. PCM_BUSINESS -> partner clearing model business consumer",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Type to filter, can be one of:\n1. LLC -> limited company\n2. PLC -> publicly listed company\n3. SOLETRADER -> sole trader\n4. OPARTNRSHP -> ordinary partnership\n5. LPARTNRSHP -> limited partnership\n6. LLP -> limited liability partnership\n7. INDIVIDUAL -> individual consumer\n8. PCM_INDIVIDUAL -> partner clearing model individual consumer\n9. PCM_BUSINESS -> partner clearing model business consumer",
              "enum": [
                "LLC",
                "PLC",
                "SOLETRADER",
                "OPARTNRSHP",
                "LPARTNRSHP",
                "LLP",
                "INDIVIDUAL",
                "PCM_INDIVIDUAL",
                "PCM_BUSINESS",
                "TRUST",
                "PREQUALIFIED"
              ]
            }
          },
          {
            "name": "verificationStatus",
            "in": "query",
            "description": "Verification Status to filter, can be one of:\n1. UNVERIFIED -> no verification checks have been completed\n2. VERIFIED -> verification checks completed satisfactorily\n3. EXVERIFIED -> verification completed externally\n4. REFERRED -> verification is pending manual review\n5. DECLINED -> verification is complete with a negative result\n6. REVIEWED -> verification check has been reviewed",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Verification Status to filter, can be one of:\n1. UNVERIFIED -> no verification checks have been completed\n2. VERIFIED -> verification checks completed satisfactorily\n3. EXVERIFIED -> verification completed externally\n4. REFERRED -> verification is pending manual review\n5. DECLINED -> verification is complete with a negative result\n6. REVIEWED -> verification check has been reviewed",
              "enum": [
                "UNVERIFIED",
                "VERIFIED",
                "EXVERIFIED",
                "REFERRED",
                "DECLINED",
                "REVIEWED"
              ]
            }
          },
          {
            "name": "fromCreatedDate",
            "in": "query",
            "description": "Customers created after and on this date. Format is 'yyyy-MM-dd'T'HH:mm:ssZ' where Z is UTC offset. e.g 2017-01-28T01:01:01+0000",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Customers created after and on this date. Format is 'yyyy-MM-dd'T'HH:mm:ssZ' where Z is UTC offset. e.g 2017-01-28T01:01:01+0000"
            }
          },
          {
            "name": "toCreatedDate",
            "in": "query",
            "description": "Customers created before and on this date. Format is 'yyyy-MM-dd'T'HH:mm:ssZ' where Z is UTC offset. e.g 2017-01-28T01:01:01+0000",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Customers created before and on this date. Format is 'yyyy-MM-dd'T'HH:mm:ssZ' where Z is UTC offset. e.g 2017-01-28T01:01:01+0000"
            }
          },
          {
            "name": "page",
            "in": "query",
            "description": "Page to fetch (0 indexed)",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "integer",
              "format": "int32",
              "description": "Page to fetch (0 indexed)",
              "minimum": 0
            }
          },
          {
            "name": "size",
            "in": "query",
            "description": "Size of Page to fetch",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "integer",
              "format": "int32",
              "description": "Size of Page to fetch",
              "exclusiveMinimum": 0,
              "maximum": 500
            }
          },
          {
            "name": "sortField",
            "in": "query",
            "description": "Sort by field. Sorted by createdDate if not present",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Sort by field. Sorted by createdDate if not present",
              "pattern": "(name|createdDate|id)"
            }
          },
          {
            "name": "sortOrder",
            "in": "query",
            "description": "Sorting order:\n1. asc -> ascendant\n2. desc -> descendant",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Sorting order:\n1. asc -> ascendant\n2. desc -> descendant",
              "pattern": "(asc|desc)"
            }
          },
          {
            "name": "externalRef",
            "in": "query",
            "description": "A list of external references to filter",
            "required": false,
            "deprecated": true,
            "style": "form",
            "explode": true,
            "schema": {
              "$ref": "#/components/schemas/account.externalRef"
            }
          },
          {
            "name": "externalReference",
            "in": "query",
            "description": "A list of external references to filter",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "$ref": "#/components/schemas/account.externalReference"
            },
            "example": "externalReference[0].type"
          },
          {
            "name": "name.type",
            "in": "query",
            "description": "WORD_MATCH - using word boundaries,\nWORD_MATCH_ALPHANUMERIC - using word boundaries, but replaces non-alphanumeric characters in the search with a word boundary match,\nPREFIX - same case prefix,\nSUFFIX - same case suffix,\nCONTAINS - same case contains\nEXACT - same case exact\n",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "WORD_MATCH - using word boundaries,\nWORD_MATCH_ALPHANUMERIC - using word boundaries, but replaces non-alphanumeric characters in the search with a word boundary match,\nPREFIX - same case prefix,\nSUFFIX - same case suffix,\nCONTAINS - same case contains\nEXACT - same case exact\n",
              "enum": [
                "WORD_MATCH",
                "WORD_MATCH_ALPHANUMERIC",
                "PREFIX",
                "SUFFIX",
                "CONTAINS",
                "EXACT"
              ]
            }
          },
          {
            "name": "name.value",
            "in": "query",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "minLength": 1
            }
          },
          {
            "name": "companyRegNumber",
            "in": "query",
            "description": "Customer registration number",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Customer registration number"
            }
          },
          {
            "name": "legalEntity",
            "in": "query",
            "description": "Customer legal entity",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Customer legal entity",
              "enum": [
                "GB",
                "NL",
                "IE"
              ]
            }
          },
          {
            "name": "contractCounterparty",
            "in": "query",
            "description": "The Modulr business unit with which the customer has contracted",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Business unit the customer contracts with",
              "enum": [
                "MFBV",
                "MFSL",
                "MUS"
              ]
            }
          },
          {
            "name": "addressLines",
            "in": "query",
            "description": "Set of the address lines. If specified, they must be present in the address line 1 or in the address line 2.\nSearch results by number may include numbers with any suffix",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "$ref": "#/components/schemas/account.addressLines"
            }
          },
          {
            "name": "postCode",
            "in": "query",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "postTown",
            "in": "query",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "country",
            "in": "query",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "associateSearchCriteria.firstNameInitial",
            "in": "query",
            "description": "Person's first name initial",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Person's first name initial",
              "maxLength": 1,
              "minLength": 1
            }
          },
          {
            "name": "associateSearchCriteria.lastName.type",
            "in": "query",
            "description": "WORD_MATCH - using word boundaries,\nWORD_MATCH_ALPHANUMERIC - using word boundaries, but replaces non-alphanumeric characters in the search with a word boundary match,\nPREFIX - same case prefix,\nSUFFIX - same case suffix,\nCONTAINS - same case contains\nEXACT - same case exact\n",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "WORD_MATCH - using word boundaries,\nWORD_MATCH_ALPHANUMERIC - using word boundaries, but replaces non-alphanumeric characters in the search with a word boundary match,\nPREFIX - same case prefix,\nSUFFIX - same case suffix,\nCONTAINS - same case contains\nEXACT - same case exact\n",
              "enum": [
                "WORD_MATCH",
                "WORD_MATCH_ALPHANUMERIC",
                "PREFIX",
                "SUFFIX",
                "CONTAINS",
                "EXACT"
              ]
            }
          },
          {
            "name": "associateSearchCriteria.lastName.value",
            "in": "query",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "minLength": 1
            }
          },
          {
            "name": "associateSearchCriteria.lastNamePrefix",
            "in": "query",
            "description": "Person's prefix",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Person's prefix"
            }
          },
          {
            "name": "associateSearchCriteria.dateOfBirth",
            "in": "query",
            "description": "Person's date of birth ",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "format": "date",
              "description": "Person's date of birth "
            }
          },
          {
            "name": "associateSearchCriteria.additionalIdentifier.type",
            "in": "query",
            "description": "Type of additional personal identifier",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Type of additional personal identifier",
              "enum": [
                "BSN"
              ]
            }
          },
          {
            "name": "associateSearchCriteria.additionalIdentifier.value",
            "in": "query",
            "description": "Personal identifier value",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "type": "string",
              "description": "Personal identifier value",
              "minLength": 1
            }
          },
          {
            "name": "associateTypes",
            "in": "query",
            "description": "List of types to filter, can be one of:\n1. DIRECTOR -> director\n2. PARTNER -> partner\n3. CSECRETARY -> company secretary\n4. SOLETRADER -> sole trader\n5. BENE_OWNER -> beneficial owner\n6. C_INTEREST -> controlling interest\n7. INDIVIDUAL -> individual\n8. PCM_INDIVIDUAL -> pcm individual\n9. SIGNATORY -> signatory\n9. TRUST_SETTLOR -> trust settlor\n9. TRUST_BENEFICIARY -> trust beneficiary\n10. TRUST_TRUSTEE -> trust trustee",
            "required": false,
            "style": "form",
            "explode": true,
            "schema": {
              "$ref": "#/components/schemas/account.associateTypes"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "OK",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/account.CustomerPageResponse"
                }
              }
            }
          },
          "400": {
            "description": "Bad Request",
            "content": {
              "*/*": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/account.MessageResponse"
                  }
                }
              }
            }
          }
        },
        "security": [
          {
            "HMAC": []
          },
          {
            "TOKEN": []
          }
        ]
      }
    }
  },
  "components": {
    "schemas": {
      "account.ScreeningResultsResponse": {
        "type": "object",
        "properties": {
          "adverseMedia": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "peps": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "sanctions": {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        }
      },
      "account.id": {
        "type": "array",
        "description": "ID of Customer(s) to fetch",
        "items": {
          "type": "string",
          "description": "ID of Customer(s) to fetch"
        }
      },
      "account.addressLines": {
        "type": "array",
        "description": "Set of the address lines. If specified, they must be present in the address line 1 or in the address line 2.\nSearch results by number may include numbers with any suffix",
        "items": {
          "type": "string",
          "description": "Set of the address lines. If specified, they must be present in the address line 1 or in the address line 2.\nSearch results by number may include numbers with any suffix"
        },
        "uniqueItems": true
      },
      "account.externalReference": {
        "type": "array",
        "description": "A list of external references to filter",
        "example": "\"externalReference[0].type\": \"WORD_MATCH\", \"externalReference[0].value\": \"Customer reference\"",
        "items": {
          "$ref": "#/components/schemas/account.StringSearchCriteria"
        }
      },
      "account.MessageResponse": {
        "type": "object",
        "properties": {
          "field": {
            "type": "string"
          },
          "code": {
            "type": "string",
            "enum": [
              "GENERAL",
              "BUSINESSRULE",
              "MFASTATUS",
              "MFAERROR",
              "MFATIMEOUT",
              "MFADEVICEMM",
              "MFAMESSAGEINVALID",
              "NOTFOUND",
              "DUPLICATE",
              "INVALID",
              "CONNECTION",
              "RETRY",
              "RATELIMIT",
              "PERMISSION",
              "NOTACCEPTABLE",
              "MFAVERIFICATION",
              "TOKENEXPIRED"
            ]
          },
          "errorCode": {
            "type": "string"
          },
          "message": {
            "type": "string"
          },
          "sourceService": {
            "type": "string"
          }
        }
      },
      "account.Customer": {
        "type": "object",
        "description": "A Customer is a single legal entity that can have 1 or more accounts",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique identifier for a Customer. Begins with 'C'",
            "example": "C00000001"
          },
          "name": {
            "type": "string",
            "description": "Customer's company name - must be unique across the Modulr platform."
          },
          "brandNames": {
            "type": "array",
            "description": "The customers brand name(s)",
            "items": {
              "$ref": "#/components/schemas/account.BrandNameResponse"
            }
          },
          "type": {
            "type": "string",
            "description": "Type of the customer, can be one of:\n1. LLC -> limited company\n2. PLC -> publicly listed company\n3. SOLETRADER -> sole trader\n4. OPARTNRSHP -> ordinary partnership\n5. LPARTNRSHP -> limited partnership\n6. LLP -> limited liability partnership\n7. INDIVIDUAL -> individual consumer\n8. PCM_INDIVIDUAL -> partner clearing model individual consumer\n9. PCM_BUSINESS -> partner clearing model business consumer"
          },
          "status": {
            "type": "string",
            "description": "Status of the Customer. Customers must be 'Active' for Accounts to be created for them.",
            "enum": [
              "ACTIVE",
              "CLOSED",
              "BLOCKED"
            ]
          },
          "verificationStatus": {
            "type": "string",
            "description": "How the identity of the Customer has been verified. Can be:\n1. UNVERIFIED -> no verification checks have been completed\n2. VERIFIED -> verification checks completed satisfactorily\n3. EXVERIFIED -> verification completed externally\n4. REFERRED -> verification is pending manual review\n5. DECLINED -> verification is complete with a negative result\n6. REVIEWED -> verification check has been reviewed"
          },
          "companyRegNumber": {
            "type": "string",
            "description": "The company registration / incorporation number of the company. Only applicable for companies registered with Companies House"
          },
          "expectedMonthlySpend": {
            "type": "integer",
            "format": "int32",
            "description": "Indication of the monthly spend of the customer."
          },
          "registeredAddress": {
            "$ref": "#/components/schemas/account.AddressResponse",
            "description": "The address of the company's registered office."
          },
          "tradingAddress": {
            "$ref": "#/components/schemas/account.AddressResponse",
            "description": "The address of the company's day-to-day trading activities."
          },
          "partnerId": {
            "type": "string",
            "description": "The owning partner identifier"
          },
          "associates": {
            "type": "array",
            "description": "Array of associate objects that link to the Customer. For example, this could contain the details of the company directors for a Limited company, or or the partners for a partnership.",
            "items": {
              "$ref": "#/components/schemas/account.AssociateResponse"
            }
          },
          "industryCode": {
            "type": "string"
          },
          "tcsVersion": {
            "type": "integer",
            "format": "int32",
            "description": "Version of the Modulr Account Terms and Conditions the Customer has agreed to."
          },
          "documentInfo": {
            "type": "array",
            "description": "Array of document objects that relate to the Customer being created. Examples of Documents could be proof of a Company Director's identity or address, Articles of Association or a Partnership Agreement.",
            "items": {
              "$ref": "#/components/schemas/account.DocumentInfo"
            }
          },
          "externalReference": {
            "type": "string"
          },
          "createdDate": {
            "type": "string",
            "format": "date-time",
            "description": "Datetime when the customer was created.Format is 'yyyy-MM-dd'T'HH:mm:ssZ' where Z is UTC offset. e.g 2017-01-28T01:01:01+0000",
            "example": "2017-01-28T01:01:01+0000"
          },
          "delegate": {
            "$ref": "#/components/schemas/account.DelegateResponse",
            "description": "Details of this Customer's linked Delegate"
          },
          "legalEntity": {
            "type": "string",
            "description": "Legal entity of the customer",
            "enum": [
              "GB",
              "NL",
              "IE"
            ]
          },
          "customerTrust": {
            "$ref": "#/components/schemas/account.CustomerTrustResponse",
            "description": "Trust nature for customers of type trust. Mandatory for type Trust, not to be set for non-trust customers."
          },
          "taxProfile": {
            "$ref": "#/components/schemas/account.CustomerTaxProfileResponse",
            "description": "Tax profile for customers of type SOLETRADER. Optional for type SOLETRADER, not to be set for non-SOLETRADER customers."
          },
          "complianceData": {
            "$ref": "#/components/schemas/account.CustomerComplianceDataResponse",
            "description": "Required for customers of type PREQUALIFIED. Not allowed for all other customer types."
          },
          "complianceSector": {
            "type": "string",
            "example": "Agency Lite Consumer"
          },
          "generateStatements": {
            "type": "boolean",
            "description": "True if the customer is configured to generate statements"
          }
        }
      },
      "account.DelegateResponse": {
        "type": "object",
        "description": "Delegate",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique reference for the Delegate.",
            "example": "D0000001"
          },
          "name": {
            "type": "string",
            "description": "Name for the Delegate"
          },
          "address": {
            "$ref": "#/components/schemas/account.AddressResponse",
            "description": "Address of the Delegate"
          },
          "roleId": {
            "type": "string",
            "description": "The id of the Role assigned to the delegate",
            "example": "R02002M5"
          },
          "externalReference": {
            "type": "string",
            "description": "External system reference for the Delegate"
          },
          "partner": {
            "type": "string",
            "description": "Partner Bid.",
            "example": "R0000001"
          },
          "status": {
            "type": "string",
            "description": "Status of the Delegate."
          },
          "created": {
            "type": "string",
            "format": "date-time",
            "description": "Datetime the Delegate was created.Format is 'yyyy-MM-dd'T'HH:mm:ssZ' where Z is UTC offset. e.g 2017-01-28T01:01:01+0000",
            "example": "2017-01-28T01:01:01+0000"
          },
          "updated": {
            "type": "string",
            "format": "date-time",
            "description": "Datetime the Delegate was last updated.Format is 'yyyy-MM-dd'T'HH:mm:ssZ' where Z is UTC offset. e.g 2017-01-28T01:01:01+0000",
            "example": "2017-01-28T01:01:01+0000"
          }
        }
      },
      "account.CustomerComplianceDataResponse": {
        "type": "object",
        "properties": {
          "typeDescription": {
            "type": "string"
          },
          "riskLevel": {
            "type": "string",
            "enum": [
              "LOW",
              "MEDIUM",
              "HIGH",
              "UNDETERMINED"
            ]
          },
          "vulnerabilityReasons": {
            "type": "array",
            "items": {
              "type": "string",
              "enum": [
                "LIFE_EVENTS",
                "HEALTH",
                "RESILIENCE",
                "CAPABILITY",
                "FINANCIAL_DIFFICULTY"
              ]
            }
          },
          "business": {
            "$ref": "#/components/schemas/account.BusinessDataResponse"
